use baal_legacy_probability_engine::{import::import_history,digest};
use serde_json::{Value,json};
use std::path::Path;
fn main(){match run(){Ok(v)=>println!("{}",v),Err(e)=>{eprintln!("{}",e);std::process::exit(1);}}}
fn run()->Result<Value,String>{let args=std::env::args().collect::<Vec<_>>();if args.len()!=2{return Err("USAGE: baal-legacy-probability-engine IMPORT_MANIFEST".into());}let manifest:Value=serde_json::from_slice(&std::fs::read(&args[1]).map_err(|_|"MANIFEST_FILE")?).map_err(|_|"MANIFEST_JSON")?;let read=|key:&str|->Result<Value,String>{serde_json::from_slice(&std::fs::read(manifest[key].as_str().ok_or("MANIFEST_PATH")?).map_err(|_|"IMPORT_FILE")?).map_err(|_|"IMPORT_JSON".into())};let bank=read("bank")?;let opening=if manifest["opening"].is_string(){Some(read("opening")?)}else{None};let imported=import_history(bank,opening,Path::new(manifest["checkpoint"].as_str().ok_or("CHECKPOINT_PATH")?),manifest["checkpointBytes"].as_u64().ok_or("CHECKPOINT_BYTES")?,manifest["checkpointSha256"].as_str().ok_or("CHECKPOINT_HASH")?,Path::new(manifest["publicSource"].as_str().ok_or("PUBLIC_PATH")?),manifest["publicBytes"].as_u64().ok_or("PUBLIC_BYTES")?,manifest["publicSha256"].as_str().ok_or("PUBLIC_HASH")?)?;let report=imported.engine.report(manifest["reportAt"].as_str().ok_or("REPORT_CLOCK")?)?;let result=json!({"evidence":imported.evidence,"stateHash":digest(imported.engine.state()),"reportHash":digest(&report),"state":imported.engine.state(),"report":report});if let Some(out)=manifest["out"].as_str(){std::fs::write(out,serde_json::to_vec(&result).unwrap()).map_err(|_|"OUTPUT_FILE")?;Ok(json!({"stateHash":result["stateHash"],"reportHash":result["reportHash"],"evidence":result["evidence"]}))}else{Ok(result)}}
